import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { resolveTicket } from '../../../store/slices/ticketsSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { UUID } from '../../../models/common';
import { Slideout } from '../../common/Slideout';
import { TextArea } from '../../common/TextArea';
import styles from './ResolveTicketModal.module.css';

export interface ResolveTicketModalProps {
  isOpen: boolean;
  ticketId: UUID;
  onClose: () => void;
  onSuccess?: () => void;
}

export const ResolveTicketModal: React.FC<ResolveTicketModalProps> = ({
  isOpen,
  ticketId,
  onClose,
  onSuccess,
}) => {
  const dispatch = useAppDispatch();
  const ticket   = useAppSelector((s) => s.tickets.selectedTicket);
  const [resolutionNote, setResolutionNote] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) setResolutionNote('');
  }, [isOpen]);

  const handleSubmit = async () => {
    if (!resolutionNote.trim()) {
      dispatch(addToast({ message: 'Vui lòng nhập ghi chú giải quyết', type: 'error' }));
      return;
    }
    setLoading(true);
    try {
      await dispatch(resolveTicket({ ticketId, resolutionNote: resolutionNote.trim() })).unwrap();
      dispatch(addToast({ message: 'Giải quyết phiếu yêu cầu thành công', type: 'success' }));
      onClose();
      onSuccess?.();
    } catch (err: any) {
      dispatch(addToast({ message: err?.message || 'Không thể giải quyết phiếu yêu cầu', type: 'error' }));
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setResolutionNote('');
    onClose();
  };

  return (
    <Slideout
      isOpen={isOpen}
      onClose={handleCancel}
      title="Giải Quyết Phiếu Yêu Cầu"
      width="520px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleCancel,
        leftDisabled: loading,
        rightLabel: loading ? 'Đang xử lý...' : 'Xác nhận giải quyết',
        rightAction: handleSubmit,
        rightDisabled: loading,
      }}
    >
      <div className={styles.form}>
        {ticket && (
          <div className={styles.summary}>
            <p className={styles.summaryLabel}>Phiếu yêu cầu</p>
            <p className={styles.summaryTitle}>{ticket.title}</p>
          </div>
        )}

        <div className={styles.field}>
          <label className={styles.label}>
            Ghi chú giải quyết <span className={styles.required}>*</span>
          </label>
          <TextArea
            value={resolutionNote}
            onChange={(e) => setResolutionNote(e.target.value)}
            placeholder="Mô tả cách vấn đề đã được giải quyết..."
            rows={5}
            disabled={loading}
          />
          <span className={styles.hint}>Bắt buộc — giải thích cách giải quyết vấn đề.</span>
        </div>
      </div>
    </Slideout>
  );
};
