/**
 * Real BFF API calls for Statistics endpoints.
 * Base route: /web-bff/api/v1/statistics
 */

import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type {
  StatisticsData,
  GoalsData,
  PersonalGoal,
  AchievementsData,
  AIInsight,
} from '../../models/Statistics';
import type { StatisticsPeriod } from '../../models/Statistics';
import type {
  BffStatisticsDto,
  BffGoalsDataDto,
  BffPersonalGoalDto,
  BffAchievementsDataDto,
  BffAIInsightDto,
} from './responseModel';
import {
  mapBffStatistics,
  mapBffGoalsData,
  mapBffGoal,
  mapBffAchievements,
  mapBffInsight,
} from './mapper';
import type { CreateGoalRequest, UpdateGoalRequest } from './requestModel';

export const statisticsEndpoint = {
  /** GET /statistics/me?period={period} */
  getStatistics: async (period: StatisticsPeriod): Promise<StatisticsData> => {
    const res = await apiClient.get<BffResponse<BffStatisticsDto>>(
      `/statistics/me?period=${encodeURIComponent(period)}`
    );
    return mapBffStatistics(unwrap(res));
  },

  /** GET /statistics/me/goals */
  getGoals: async (): Promise<GoalsData> => {
    const res = await apiClient.get<BffResponse<BffGoalsDataDto>>('/statistics/me/goals');
    return mapBffGoalsData(unwrap(res));
  },

  /** POST /statistics/me/goals */
  createGoal: async (req: CreateGoalRequest): Promise<PersonalGoal> => {
    const res = await apiClient.post<BffResponse<BffPersonalGoalDto>>('/statistics/me/goals', req);
    return mapBffGoal(unwrap(res));
  },

  /** PATCH /statistics/me/goals/{id} */
  updateGoal: async (goalId: string, req: UpdateGoalRequest): Promise<PersonalGoal> => {
    const res = await apiClient.patch<BffResponse<BffPersonalGoalDto>>(
      `/statistics/me/goals/${goalId}`,
      req
    );
    return mapBffGoal(unwrap(res));
  },

  /** DELETE /statistics/me/goals/{id} */
  deleteGoal: async (goalId: string): Promise<void> => {
    await apiClient.delete<BffResponse<object>>(`/statistics/me/goals/${goalId}`);
  },

  /** GET /statistics/me/insights */
  getInsights: async (): Promise<AIInsight[]> => {
    const res = await apiClient.get<BffResponse<BffAIInsightDto[]>>('/statistics/me/insights');
    return unwrap(res).map(mapBffInsight);
  },

  /** GET /statistics/me/achievements */
  getAchievements: async (): Promise<AchievementsData> => {
    const res = await apiClient.get<BffResponse<BffAchievementsDataDto>>(
      '/statistics/me/achievements'
    );
    return mapBffAchievements(unwrap(res));
  },

  /** GET /statistics/me/export?period={period} → Blob (PDF) */
  exportReport: async (period: StatisticsPeriod): Promise<Blob> => {
    return apiClient.get(`/statistics/me/export?period=${encodeURIComponent(period)}`) as unknown as Blob;
  },
};
