/**
 * Notification API endpoint calls.
 *
 * All calls use the shared apiClient (Bearer token injected automatically).
 * Route prefix: web-bff/api/v1/notifications
 *
 * Subscription API (mute/unmute per entity):
 * Route prefix: web-bff/api/v1/subscriptions
 */
import { apiClient } from '../api';
import { unwrap } from '../shared/bffEnvelope';
import type { BffResponse } from '../shared/bffEnvelope';
import type {
  NotificationDto,
  NotificationPagedResult,
  UnreadCountDto,
} from './types';

const BASE = '/notifications';
const SUB_BASE = '/subscriptions';

// ── Subscription types ────────────────────────────────────────────────────────

export interface SubscriptionStateDto {
  isMuted: boolean;
}

// ── Notification endpoints ────────────────────────────────────────────────────

export const notificationEndpoint = {
  /**
   * GET /notifications?unreadOnly=&page=&pageSize=
   */
  getNotifications: async (
    unreadOnly = false,
    page       = 1,
    pageSize   = 20,
  ): Promise<NotificationPagedResult> => {
    const params = new URLSearchParams({
      unreadOnly: String(unreadOnly),
      page:       String(page),
      pageSize:   String(pageSize),
    });
    const res = await apiClient.get<BffResponse<NotificationPagedResult>>(
      `${BASE}?${params}`
    );
    return unwrap(res);
  },

  /**
   * GET /notifications/unread-count
   */
  getUnreadCount: async (): Promise<number> => {
    const res = await apiClient.get<BffResponse<UnreadCountDto>>(
      `${BASE}/unread-count`
    );
    return unwrap(res).count;
  },

  /**
   * PATCH /notifications/{id}/read
   */
  markRead: async (id: string): Promise<void> => {
    await apiClient.patch<BffResponse<unknown>>(`${BASE}/${id}/read`, {});
  },

  /**
   * PATCH /notifications/mark-all-read
   */
  markAllRead: async (): Promise<void> => {
    await apiClient.patch<BffResponse<unknown>>(`${BASE}/mark-all-read`, {});
  },

  /**
   * DELETE /notifications/{id}
   */
  deleteNotification: async (id: string): Promise<void> => {
    await apiClient.delete<void>(`${BASE}/${id}`);
  },

  /**
   * PATCH /notifications/clear-all
   */
  clearAll: async (): Promise<void> => {
    await apiClient.delete<void>(`${BASE}/clear-all`);
  },

  /**
   * PATCH /notifications/mark-read-by-entity
   * Mark all unread notifications for a specific entity (and optionally types)
   * as read. Used when the user opens the chat or comments tab.
   */
  markReadByEntity: async (
    entityId: string,
    types?: string[],
  ): Promise<void> => {
    await apiClient.patch<BffResponse<unknown>>(`${BASE}/mark-read-by-entity`, {
      entityId,
      types,
    });
  },
};

// ── Subscription endpoints (mute / unmute per entity) ─────────────────────────

export const subscriptionEndpoint = {
  /**
   * GET /subscriptions/{entityType}/{entityId}
   * Returns { isMuted: boolean }. Defaults to false when no row exists.
   */
  getSubscription: async (
    entityType: 'ticket' | 'task',
    entityId: string,
  ): Promise<SubscriptionStateDto> => {
    const res = await apiClient.get<BffResponse<SubscriptionStateDto>>(
      `${SUB_BASE}/${entityType}/${entityId}`
    );
    return unwrap(res);
  },

  /**
   * PUT /subscriptions/{entityType}/{entityId}
   * Upsert mute preference. Returns updated { isMuted: boolean }.
   */
  updateSubscription: async (
    entityType: 'ticket' | 'task',
    entityId: string,
    isMuted: boolean,
  ): Promise<SubscriptionStateDto> => {
    const res = await apiClient.put<BffResponse<SubscriptionStateDto>>(
      `${SUB_BASE}/${entityType}/${entityId}`,
      { isMuted }
    );
    return unwrap(res);
  },
};

// ── Typed service aliases (backwards compatibility) ───────────────────────────

export const notificationService  = notificationEndpoint;
export const subscriptionService  = subscriptionEndpoint;

// ── Default export for convenience ───────────────────────────────────────────

export default notificationService;

// Re-export types so consumers only import from this module
export type { NotificationDto, NotificationPagedResult, UnreadCountDto };
