import React from 'react';
import styles from './SLABadge.module.css';

export interface SLABadgeProps {
  status: 'danger' | 'warning' | 'safe' | 'breached';
  timeRemaining: string;
  compact?: boolean;
}

export const SLABadge: React.FC<SLABadgeProps> = ({ status, timeRemaining, compact = false }) => {
  return (
    <span className={`${styles.badge} ${styles[status]} ${compact ? styles.compact : ''}`}>
      <span className={styles.dot}></span>
      <span className={styles.time}>{timeRemaining}</span>
    </span>
  );
};

// Helper function to format time remaining
export const formatSLATime = (minutes: number): string => {
  if (minutes < 0) return 'Quá hạn';
  if (minutes < 60) return `${minutes} phút`;
  if (minutes < 1440) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
  }
  const days = Math.floor(minutes / 1440);
  const hours = Math.floor((minutes % 1440) / 60);
  return hours > 0 ? `${days} ngày ${hours}h` : `${days} ngày`;
};

// Helper to determine SLA status from percentage
export const getSLAStatus = (percentage: number, breached: boolean): SLABadgeProps['status'] => {
  if (breached) return 'breached';
  if (percentage < 10) return 'danger';
  if (percentage < 25) return 'warning';
  return 'safe';
};
