import React, { useState } from 'react';
import styles from './TwoLineTable.module.css';

export interface TwoLineTableColumn {
  key: string;
  label: string;
  width?: string;
}

export interface TwoLineTableRow<T> {
  id: string;
  data: T;
  line1Content: React.ReactNode;
  line2Cells: React.ReactNode[];
  // For expandable actions mode
  idElement?: React.ReactNode;
  actionsContent?: React.ReactNode;
}

export interface TwoLineTableProps<T> {
  columns: TwoLineTableColumn[];
  rows: TwoLineTableRow<T>[];
  loading?: boolean;
  emptyMessage?: {
    icon?: string;
    title: string;
    description?: string;
  };
  onRowClick?: (data: T) => void;
  onIdClick?: (data: T) => void; // Separate handler for ID clicks
  className?: string;
  isMobile?: boolean;
  expandableActions?: boolean; // Enable expandable actions mode
}

export const TwoLineTable = <T,>({
  columns,
  rows,
  loading = false,
  emptyMessage,
  onRowClick,
  onIdClick,
  className,
  isMobile = false,
  expandableActions = false,
}: TwoLineTableProps<T>) => {
  const [expandedRowId, setExpandedRowId] = useState<string | null>(null);

  const handleCardClick = (rowId: string, data: T) => {
    if (expandableActions) {
      // Toggle expanded state
      setExpandedRowId(expandedRowId === rowId ? null : rowId);
    } else if (onRowClick) {
      onRowClick(data);
    }
  };

  const handleIdClick = (e: React.MouseEvent, data: T) => {
    e.stopPropagation(); // Prevent card click
    if (onIdClick) {
      onIdClick(data);
    }
  };
  if (loading) {
    return (
      <div className={styles.loadingCard}>
        <div className={styles.loading}>
          <i className="fas fa-spinner fa-spin"></i> Đang tải...
        </div>
      </div>
    );
  }

  if (rows.length === 0 && emptyMessage) {
    return (
      <div className={styles.emptyCard}>
        <div className={styles.empty}>
          {emptyMessage.icon && <i className={emptyMessage.icon}></i>}
          <p className={styles.emptyTitle}>{emptyMessage.title}</p>
          {emptyMessage.description && (
            <p className={styles.emptyDescription}>{emptyMessage.description}</p>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className={`${styles.tableCard} ${className || ''}`}>
      <div className={styles.tableWrapper}>
        <table className={styles.table}>
            <thead>
              <tr>
                {columns.map((col) => (
                  <th key={col.key} style={{ width: col.width }}>
                    {col.label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => {
                const isExpanded = expandableActions && expandedRowId === row.id;
                return (
                  <React.Fragment key={row.id}>
                    {/* Line 1: Main content spanning all columns */}
                    <tr
                      className={`${styles.line1Row} ${isExpanded ? styles.expanded : ''}`}
                      onClick={() => handleCardClick(row.id, row.data)}
                    >
                      <td colSpan={columns.length} className={styles.line1Cell}>
                        <div
                          className={`${styles.line1CellGroup} ${
                            isMobile ? styles.line1CellGroupMobile : ''
                          }`}
                        >
                          {expandableActions && row.idElement ? (
                            <>
                              <span
                                className={styles.idClickZone}
                                onClick={(e) => handleIdClick(e, row.data)}
                              >
                                {row.idElement}
                              </span>
                              {row.line1Content}
                            </>
                          ) : (
                            row.line1Content
                          )}
                        </div>
                      </td>
                    </tr>
                    {/* Line 2: Column data */}
                    <tr
                      className={`${styles.line2Row} ${isExpanded ? styles.expanded : ''}`}
                      onClick={() => handleCardClick(row.id, row.data)}
                    >
                      <td colSpan={columns.length} className={styles.line2Wrapper}>
                        <div className={`${styles.line2Container} ${isExpanded ? styles.blurred : ''}`}>
                          {row.line2Cells.map((cell, index) => (
                            <div
                              key={`${row.id}-${index}`}
                              className={styles.line2Cell}
                              style={{ width: columns[index].width }}
                              data-label={columns[index].label}
                            >
                              <div className={styles.cellContent}>{cell}</div>
                            </div>
                          ))}
                        </div>
                        {/* Actions overlay */}
                        {expandableActions && isExpanded && row.actionsContent && (
                          <div className={styles.actionsOverlay} onClick={(e) => e.stopPropagation()}>
                            {row.actionsContent}
                          </div>
                        )}
                      </td>
                    </tr>
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
  );
};
