import React, { useState } from 'react';
import { Button } from '../../../components/common/Button';
import { Slideout } from '../../../components/common/Slideout';
import {
  UserMultiSearchInput,
  SelectedUser,
} from '../../../components/common/UserSearchInput/UserMultiSearchInput';
import { UUID } from '../../../models/common';
import { SupportRequest } from '../../../models/Task';
import { useAppToast } from '../../../hooks/useAppToast';
import styles from './AssignCollaboratorModal.module.css';

interface AssignCollaboratorModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (collaborators: {
    userId: UUID;
    userName: string;
    role: 'support' | 'reviewer' | 'contributor';
    effortPercentage: number;
  }[]) => Promise<void>;
  supportRequest?: SupportRequest;
  taskTitle: string;
  /** User IDs to exclude from the picker (current assignee + active collaborators) */
  excludeUserIds?: string[];
}

const AssignCollaboratorModal: React.FC<AssignCollaboratorModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  supportRequest,
  taskTitle,
  excludeUserIds = [],
}) => {
  const [selectedUsers, setSelectedUsers] = useState<SelectedUser[]>([]);
  const [role, setRole] = useState<'support' | 'reviewer' | 'contributor'>('support');
  const [effortPercentage, setEffortPercentage] = useState(30);
  const [submitting, setSubmitting] = useState(false);
  const toast = useAppToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedUsers.length === 0) return;

    setSubmitting(true);
    try {
      const collaborators = selectedUsers.map((u) => ({
        userId: u.userId,
        userName: u.fullName,
        role,
        effortPercentage: Math.floor(effortPercentage / selectedUsers.length),
      }));

      await onSubmit(collaborators);
      handleClose();
    } catch (error: unknown) {
      toast.fromError(error, 'Đã có lỗi khi phân công, vui lòng thử lại');
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setSelectedUsers([]);
    setRole('support');
    setEffortPercentage(30);
    onClose();
  };

  const footerContent = (
    <>
      <Button
        type="button"
        variant="secondary"
        onClick={handleClose}
        disabled={submitting}
      >
        Hủy
      </Button>
      <button
        type="submit"
        form="assign-collaborator-form"
        className={styles.submitBtn}
        disabled={selectedUsers.length === 0 || submitting}
      >
        {submitting ? (
          <>
            <i className="fas fa-spinner fa-spin"></i> Đang chỉ định...
          </>
        ) : (
          <>
            <i className="fas fa-user-check"></i> Chỉ định Collaborator
          </>
        )}
      </button>
    </>
  );

  return (
    <Slideout
      isOpen={isOpen}
      onClose={handleClose}
      title={
        <>
          <i className="fas fa-user-plus"></i> Chỉ định Collaborator
        </>
      }
      width="700px"
      customFooter={footerContent}
    >
      <form id="assign-collaborator-form" onSubmit={handleSubmit}>
        <div className={styles.modalBody}>
          <div className={styles.infoBox}>
            <i className="fas fa-info-circle"></i>
            <div>
              <strong>Task:</strong> {taskTitle}
              {supportRequest && (
                <>
                  <p className={styles.requestDescription}>
                    <strong>Yêu cầu hỗ trợ:</strong> {supportRequest.description}
                  </p>
                  <p className={styles.requestReason}>
                    <strong>Lý do:</strong> {supportRequest.reason}
                  </p>
                </>
              )}
            </div>
          </div>

          <UserMultiSearchInput
            value={selectedUsers}
            onChange={setSelectedUsers}
            excludeUserIds={excludeUserIds}
            label="Chọn Collaborator"
            placeholder="Nhập mã hoặc tên để tìm..."
            showDepartmentFilter
            inline
            required
            error={undefined}
          />

          <div className={styles.formRow}>
            <div className={styles.formGroup}>
              <label className={styles.label}>Vai trò</label>
              <select
                className={styles.select}
                value={role}
                onChange={(e) => setRole(e.target.value as any)}
              >
                <option value="support">Hỗ trợ (Support)</option>
                <option value="contributor">Đóng góp (Contributor)</option>
                <option value="reviewer">Đánh giá (Reviewer)</option>
              </select>
            </div>

            <div className={styles.formGroup}>
              <label className={styles.label}>Effort %</label>
              <div className={styles.effortInput}>
                <input
                  type="number"
                  min="5"
                  max="50"
                  step="5"
                  value={effortPercentage}
                  onChange={(e) => setEffortPercentage(Number(e.target.value))}
                  className={styles.numberInput}
                />
                <span className={styles.effortUnit}>%</span>
              </div>
            </div>
          </div>

          {selectedUsers.length > 0 && (
            <div className={styles.selectedSummary}>
              <i className="fas fa-users"></i>
              <span>
                Đã chọn {selectedUsers.length} collaborator(s) - mỗi người ~
                {Math.floor(effortPercentage / selectedUsers.length)}% effort
              </span>
            </div>
          )}
        </div>
      </form>
    </Slideout>
  );
};

export default AssignCollaboratorModal;
