/**
 * ReportFilters Component
 * Quick filter controls for report parameters — responsive (mobile toggle + desktop row)
 */

import React, { useState } from 'react';
import { ReportPeriod, type ReportFilters as ReportFiltersType } from '../../../models/Report';
import { Select, SelectOption } from '../../common';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './ReportFilters.module.css';

interface ReportFiltersProps {
  filters: ReportFiltersType;
  onFiltersChange: (filters: ReportFiltersType) => void;
}

const PERIOD_OPTIONS: SelectOption[] = [
  { value: ReportPeriod.Last7Days,   label: '7 ngày qua' },
  { value: ReportPeriod.Last30Days,  label: '30 ngày qua' },
  { value: ReportPeriod.ThisMonth,   label: 'Tháng này' },
  { value: ReportPeriod.ThisQuarter, label: 'Quý này' },
  { value: ReportPeriod.ThisYear,    label: 'Năm này' },
];

const DEPT_OPTIONS: SelectOption[] = [
  { value: '',          label: 'Tất cả phòng ban' },
  { value: 'emergency', label: 'Cấp cứu' },
  { value: 'surgery',   label: 'Ngoại khoa' },
  { value: 'internal',  label: 'Nội khoa' },
  { value: 'it',        label: 'Hỗ trợ IT' },
];

const TEAM_OPTIONS: SelectOption[] = [
  { value: '',       label: 'Tất cả teams' },
  { value: 'team-a', label: 'Team A' },
  { value: 'team-b', label: 'Team B' },
  { value: 'team-c', label: 'Team C' },
];

export const ReportFilters: React.FC<ReportFiltersProps> = ({ filters, onFiltersChange }) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);

  const activeFilterCount =
    (filters.period !== ReportPeriod.ThisMonth ? 1 : 0) +
    (filters.department ? 1 : 0) +
    (filters.team ? 1 : 0);

  const handleChange =
    (key: keyof ReportFiltersType) =>
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      onFiltersChange({ ...filters, [key]: e.target.value });
    };

  // ─── Mobile ───────────────────────────────────────────────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && (
          <div className={styles.backdrop} onClick={() => setIsExpanded(false)} />
        )}
        <div className={styles.container}>
          <div className={styles.mobileHeader}>
            <span className={styles.title}>Bộ lọc</span>
            <button
              className={styles.filterToggle}
              onClick={() => setIsExpanded((v) => !v)}
              type="button"
              aria-expanded={isExpanded}
            >
              <i className="fas fa-filter" />
              {activeFilterCount > 0 && (
                <span className={styles.filterBadge}>{activeFilterCount}</span>
              )}
              <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
            </button>
          </div>
          {isExpanded && (
            <div className={styles.mobileFilters}>
              <Select
                value={filters.period}
                onChange={handleChange('period')}
                options={PERIOD_OPTIONS}
                fullWidth
              />
              <Select
                value={filters.department ?? ''}
                onChange={handleChange('department')}
                options={DEPT_OPTIONS}
                fullWidth
              />
              <Select
                value={filters.team ?? ''}
                onChange={handleChange('team')}
                options={TEAM_OPTIONS}
                fullWidth
              />
            </div>
          )}
        </div>
      </>
    );
  }

  // ─── Desktop ──────────────────────────────────────────────────────────────
  return (
    <div className={styles.container}>
      <div className={styles.row}>
        <Select
          value={filters.period}
          onChange={handleChange('period')}
          options={PERIOD_OPTIONS}
          size="small"
        />
        <Select
          value={filters.department ?? ''}
          onChange={handleChange('department')}
          options={DEPT_OPTIONS}
          size="small"
        />
        <Select
          value={filters.team ?? ''}
          onChange={handleChange('team')}
          options={TEAM_OPTIONS}
          size="small"
        />
      </div>
    </div>
  );
};
